define dso_local void @test_atomic_cmpxchg_i64(i64 %wanted, i64 %new) #0 {
  %pair = cmpxchg ptr @var64, i64 %wanted, i64 %new monotonic monotonic, align 8
  %old = extractvalue { i64, i1 } %pair, 0
  store i64 %old, ptr @var64, align 4
  ret void
}

